import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import RegisterCard from './pages/RegisterCard';

function App() {
  return (
    <Router>
      <div className="min-h-screen bg-slate-950 text-white flex flex-col">
        <nav className="bg-slate-900 border-b border-slate-800 px-6 py-4 flex justify-between items-center shadow-md">
          <div className="flex items-center space-x-3">
            <span className="w-3 h-3 bg-indigo-500 rounded-full animate-pulse"></span>
            <h1 className="text-lg font-bold tracking-wide text-white">Smart Attendance System</h1>
          </div>
          <div className="space-x-6 text-sm font-medium">
            <Link to="/" className="text-indigo-400 hover:text-indigo-300 transition">Register Card</Link>
          </div>
        </nav>
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<RegisterCard />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
